def process_post_deletion_tasks(object, user, ip)
    create_audit_entry(object, user, ip)
  end

def self.chatwoot_domain?(domain = request.host)
    [URI.parse(ENV.fetch('FRONTEND_URL', '')).host, URI.parse(ENV.fetch('HELPCENTER_URL', '')).host].include?(domain)
  end

def initialize(account, waba_info, phone_info, access_token)
    @account = account
    @waba_info = waba_info
    @phone_info = phone_info
    @access_token = access_token
  end

def edit
    @group.build_admin_note unless @group.admin_note
  end

def filter_pods(pod, service)
      pod["metadata"]["labels"]["serving.knative.dev/service"] == service
    end

def strip_heredoc(str)
  str.gsub(/^#{str.scan(/^[ \t]*(?=\S)/).min}/, "".freeze)
end

def merge_value_to_request_store(resource_klass, resource_id, value)
      Gitlab::SafeRequestLoader.execute(
        resource_key: max_member_access_for_resource_key(resource_klass),
        resource_ids: [resource_id],
        default_value: Gitlab::Access::NO_ACCESS
      ) do
        { resource_id => value }
      end
    end
